<?php require __DIR__.'/../config/bootstrap.php'; ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MANJU Admin</title><script src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js"></script><style>body{margin:0;font-family:Arial;background:#f4f8fc;color:#123b63}.wrap{max-width:1150px;margin:35px auto;padding:0 18px}.box{background:#fff;border:1px solid #d8e4ef;border-radius:15px;padding:22px;margin-bottom:20px}input,select{width:100%;padding:12px;border:1px solid #cbdbe9;border-radius:8px;box-sizing:border-box}.grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field{margin:8px 0}.field label{display:block;font-size:13px;font-weight:bold;margin-bottom:6px}.btn{border:0;background:#0b3158;color:#fff;padding:12px 16px;border-radius:8px;font-weight:bold;cursor:pointer}.orange{background:#ff8300}.red{background:#d84b4b}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:15px}.tablewrap{overflow:auto}.table{border-collapse:collapse;width:100%;min-width:900px}.table th,.table td{padding:10px;border-bottom:1px solid #d8e4ef;text-align:left;font-size:12px}.table th{background:#edf5fb}.hide{display:none}.msg{padding:10px;border-radius:8px;background:#edf6ff;margin:10px 0}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap">
<div id="login" class="box" style="max-width:420px;margin:80px auto"><h2>🔐 MANJU Admin Login</h2><p>Private shipment management</p><input id="username" placeholder="Username"><br><br><input id="password" type="password" placeholder="Password"><button class="btn orange" style="width:100%;margin-top:12px" onclick="login()">Login</button><div id="loginMsg"></div></div>
<div id="dash" class="hide"><div class="box"><h1>⚙️ MANJU Admin Panel</h1><p>Customer data and actual courier AWBs are managed server-side.</p><button class="btn" onclick="logout()">Logout</button></div><div class="box"><h2>➕ Create / Map Shipment</h2><div class="grid"><div class="field"><label>Customer Name</label><input id="customer"></div><div class="field"><label>Courier</label><select id="courier"><option>DHL</option><option>FedEx</option><option>DTDC</option><option>Aramex</option><option>UPS</option><option>Blue Dart</option></select></div><div class="field"><label>Actual Courier AWB</label><input id="awb"></div><div class="field"><label>Destination</label><input id="destination"></div><div class="field"><label>Status</label><select id="status"><option>Booked</option><option>Picked Up</option><option>In Transit</option><option>Out for Delivery</option><option>Delivered</option></select></div></div><button class="btn orange" onclick="createShipment()">Generate MANJU Tracking Number</button><div id="created"></div></div>
<div class="box"><h2>📊 Excel</h2><p>Export the server database to an Excel file, edit it, then import it back. Actual AWBs never appear in the public customer page.</p><div class="actions"><button class="btn" onclick="exportExcel()">⬇ Export Excel</button><label class="btn" style="cursor:pointer">⬆ Import Excel <input id="excel" type="file" accept=".xlsx,.xls,.csv" hidden onchange="importExcel(event)"></label></div></div>
<div class="box"><h2>📦 Shipments</h2><div class="tablewrap"><table class="table"><thead><tr><th>MANJU No.</th><th>Customer</th><th>Courier</th><th>Actual AWB</th><th>Destination</th><th>Status</th><th>Created</th></tr></thead><tbody id="rows"></tbody></table></div></div></div></div><script src="admin.js"></script></body></html>
